# connected components of same color (excluding 0 and 3)
def components(grid):
    h=len(grid);w=len(grid[0]);seen=set();comps=[]
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v in (0,3) or (r,c) in seen: continue
            stack=[(r,c)];seen.add((r,c));cells=[]
            while stack:
                rr,cc=stack.pop();cells.append((rr,cc))
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        nr,nc=rr+dr,cc+dc
                        if 0<=nr<h and 0<=nc<w and grid[nr][nc]==v and (nr,nc) not in seen:
                            seen.add((nr,nc));stack.append((nr,nc))
            comps.append((v,tuple(sorted(cells))))
    return comps
