def find_frames(gi):
    H,W=len(gi),len(gi[0]); res=[]
    for r in range(H-1):
        for c in range(W-1):
            for h in range(3,min(H-r,W-c)+1):
                perim=[gi[rr][cc] for rr in range(r,r+h) for cc in range(c,c+h) if rr in (r,r+h-1) or cc in (c,c+h-1)]
                inter=[gi[rr][cc] for rr in range(r+1,r+h-1) for cc in range(c+1,c+h-1)]
                b=perim[0]
                if len(set(perim))==1 and len(set(inter))==1 and set(inter)!={b}:
                    res.append((r,c,h,b,list(inter)[0]))
    return res

