def f2(gi):
    g=[row[:] for row in gi]; H,W=len(gi),len(gi[0])
    fr=find_frames(gi)
    # horizontal corridors
    byband={}
    for (r,c,h,b,m) in fr: byband.setdefault(r,[]).append((r,c,h,b,m))
    for r,fs in byband.items():
        from collections import defaultdict
        bm=defaultdict(list)
        for (rr,cc,hh,bv,mm) in fs: bm[mm].append((rr,cc,hh,bv))
        for mm,items in bm.items():
            items_s=sorted(items,key=lambda t:t[1])
            for i in range(len(items_s)-1):
                (r1,c1,h1,b1),(r2,c2,h2,b2)=items_s[i],items_s[i+1]
                ir=r1+(h1-1)//2
                for c in range(c1+h1-1+1,c2):
                    if g[ir][c]==0: g[ir][c]=mm
    # vertical corridors
    from collections import defaultdict
    vm=defaultdict(list)
    for (r,c,h,b,m) in fr:
        ic=c+(h-1)//2
        vm[(ic,m)].append((r,c,h,b,m))
    for (ic,m),items in vm.items():
        items_s=sorted(items,key=lambda t:t[0])
        for i in range(len(items_s)-1):
            (r1,c1,h1,b1,m1),(r2,c2,h2,b2,m2)=items_s[i],items_s[i+1]
            if m1!=m2: continue
            ir1=r1+(h1-1)//2; ir2=r2-(h2-1)//2
            # interior column span of both frames
            ia1=list(range(c1+1,c1+h1-1)); ia2=list(range(c2+1,c2+h2-1))
            ic_range=set(ia1)&set(ia2)
            if not ic_range: continue
            for rr in range(r1+h1-1+1,r2):
                for cc in ic_range:
                    if g[rr][cc]==0: g[rr][cc]=m
    return g

